#!/usr/bin/env node
/*
 * Builds dist/Finalsay.gs: every script file in src/ joined into one, in load order, so the script can be
 * installed with one paste instead of eight. The two HTML files and the manifest stay separate files.
 * Run: npm run build      Check only (used by the tests): node tools/bundle.js --print
 */
const fs = require('node:fs');
const path = require('node:path');

const ROOT = path.join(__dirname, '..');
const ORDER = ['Core.js', 'Store.gs', 'Mail.gs', 'Ai.gs', 'Cal.gs', 'Docs.gs', 'Intake.gs', 'Code.gs'];

function build() {
  const parts = ORDER.map((f) => {
    const text = fs.readFileSync(path.join(ROOT, 'src', f), 'utf8').replace(/\s+$/, '');
    return '// ' + '='.repeat(100) + '\n// ' + f + '\n// ' + '='.repeat(100) + '\n' + text + '\n';
  });
  return [
    '/**',
    ' * Finalsay, all script files in one. GENERATED by tools/bundle.js from the files in src/. Do not edit here:',
    ' * edit the file in src/ and run "npm run build".',
    ' *',
    ' * Install: paste this whole file into the Apps Script editor as "Code", add the HTML files "Board" and "App",',
    ' * and replace appsscript.json. See SETUP.md step 1.',
    ' *',
    ' * MIT License. Copyright (c) Bhavesh Vaghela.',
    ' */',
    ''
  ].join('\n') + '\n' + parts.join('\n');
}

if (require.main === module) {
  const out = build();
  if (process.argv.includes('--print')) process.stdout.write(out);
  else {
    fs.mkdirSync(path.join(ROOT, 'dist'), { recursive: true });
    fs.writeFileSync(path.join(ROOT, 'dist', 'Finalsay.gs'), out);
    console.log('dist/Finalsay.gs ' + Math.round(out.length / 1024) + ' KB, ' + ORDER.length + ' files');
  }
}
module.exports = { build, ORDER };
